UPDATE MB_REFRESH_TOKEN
   SET REVOKED_YN   = 'Y',
       REVOKED_DATE = SYSDATE,
       REPLACED_BY  = #{replacedBy, jdbcType=NUMERIC}
 WHERE TOKEN_NO   = #{tokenNo, jdbcType=NUMERIC}
   AND REVOKED_YN = 'N'

UPDATE MB_REFRESH_TOKEN
   SET REPLACED_BY = #{replacedBy, jdbcType=NUMERIC}
 WHERE TOKEN_NO = #{tokenNo, jdbcType=NUMERIC}

UPDATE MB_REFRESH_TOKEN
   SET REVOKED_YN = 'Y', REVOKED_DATE = SYSDATE
 WHERE PERSON_ID  = #{personId, jdbcType=VARCHAR}
   AND DEVICE_ID  = #{deviceId, jdbcType=VARCHAR}
   AND REVOKED_YN = 'N'

UPDATE MB_REFRESH_TOKEN
   SET REVOKED_YN = 'Y', REVOKED_DATE = SYSDATE
 WHERE PERSON_ID  = #{personId, jdbcType=VARCHAR}
   AND REVOKED_YN = 'N'

   AND DEVICE_ID <> #{exceptDeviceId, jdbcType=VARCHAR}

UPDATE MB_DEVICE
   SET FCM_TOKEN   = #{fcmToken, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE
 WHERE DEVICE_ID = #{deviceId, jdbcType=VARCHAR}
   AND PERSON_ID = #{personId, jdbcType=VARCHAR}

UPDATE MB_DEVICE
   SET LANG        = #{deviceLang, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE
 WHERE DEVICE_ID = #{deviceId, jdbcType=VARCHAR}
   AND PERSON_ID = #{personId, jdbcType=VARCHAR}
   AND (LANG IS NULL OR LANG <> #{deviceLang, jdbcType=VARCHAR})

UPDATE MB_DEVICE
   SET ACTIVITY    = 0,
       FCM_TOKEN   = NULL,
       UPDATE_DATE = SYSDATE
 WHERE DEVICE_ID = #{deviceId, jdbcType=VARCHAR}
   AND PERSON_ID = #{personId, jdbcType=VARCHAR}
